// TypeScript Version: 4.1

/**
* Interface describing `snannsumkbn`.
*/
interface Routine {
	/**
	* Computes the sum of single-precision floating-point strided array elements, ignoring `NaN` values, using an improved Kahan–Babuška algorithm, and returns the number of non-`NaN` elements.
	*
	* @param N - number of indexed elements
	* @param x - input array
	* @param strideX - stride length for `x`
	* @param sum - output array for storing the sum
	* @param count - output array for storing the number of non-NaN elements
	* @returns `sum`
	*
	* @example
	* var Float32Array = require( '@stdlib/array/float32' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var x = new Float32Array( [ 1.0, -2.0, NaN, 2.0 ] );
	* var sum = new Float32Array( 1 );
	* var count = new Int32Array( 1 );
	*
	* var v = snannsumkbn( x.length, x, 1, sum, count );
	* // returns <Float32Array>[ 1.0 ]
	*/
	( N: number, x: Float32Array, strideX: number, sum: Float32Array, count: Int32Array ): Float32Array;

	/**
	* Computes the sum of single-precision floating-point strided array elements, ignoring `NaN` values, using an improved Kahan–Babuška algorithm and alternative indexing semantics, and returns the number of non-`NaN` elements.
	*
	* @param N - number of indexed elements
	* @param x - input array
	* @param strideX - stride length for `x`
	* @param offsetX - starting index for `x`
	* @param sum - output array for storing the sum
	* @param offsetSum - starting index for `sum`
	* @param count - output array for storing the number of non-NaN elements
	* @param offsetCount - starting index for `count`
	* @returns `sum`
	*
	* @example
	* var Float32Array = require( '@stdlib/array/float32' );
	* var Int32Array = require( '@stdlib/array/int32' );
	*
	* var x = new Float32Array( [ 1.0, -2.0, NaN, 2.0 ] );
	* var sum = new Float32Array( 1 );
	* var count = new Int32Array( 1 );
	*
	* var v = snannsumkbn.ndarray( x.length, x, 1, 0, sum, 0, count, 0 );
	* // returns <Float32Array>[ 1.0 ]
	*/
	ndarray( N: number, x: Float32Array, strideX: number, offsetX: number, sum: Float32Array, offsetSum: number, count: Int32Array, offsetCount: number ): Float32Array; // eslint-disable-line max-len
}

/**
* Computes the sum of single-precision floating-point strided array elements, ignoring `NaN` values, using an improved Kahan–Babuška algorithm, and returns the number of non-`NaN` elements.
*
* @param N - number of indexed elements
* @param x - input array
* @param strideX - stride length for `x`
* @param sum - output array for storing the sum
* @param count - output array for storing the number of non-NaN elements
* @returns `sum`
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var x = new Float32Array( [ 1.0, -2.0, NaN, 2.0 ] );
* var sum = new Float32Array( 1 );
* var count = new Int32Array( 1 );
*
* var v = snannsumkbn( x.length, x, 1, sum, count );
* // returns <Float32Array>[ 1.0 ]
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var Int32Array = require( '@stdlib/array/int32' );
*
* var x = new Float32Array( [ 1.0, -2.0, NaN, 2.0 ] );
* var sum = new Float32Array( 1 );
* var count = new Int32Array( 1 );
*
* var v = snannsumkbn.ndarray( x.length, x, 1, 0, sum, 0, count, 0 );
* // returns <Float32Array>[ 1.0 ]
*/
declare var snannsumkbn: Routine;


// EXPORTS //

export = snannsumkbn;
